package com.bank.analytics;

import java.util.*;
import java.util.logging.*;

public class AtMostKDistinctDemo {
    private static final Logger log = Logger.getLogger(AtMostKDistinctDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SpendPatternAnalyzer analyzer = new SpendPatternAnalyzer();

        // Merchant category codes per transaction
        int[] categories = {1, 2, 1, 2, 3, 2, 2};
        int k = 2;
        int longest = analyzer.longestWithinKCategories(categories, k);
        log.info(() -> "Longest run within " + k + " categories: " + longest);
    }
}

