class SpendPatternAnalyzer {
    private static final Logger log = Logger.getLogger(SpendPatternAnalyzer.class.getName());

    // Variable window, at most K distinct. O(n) time, O(k) space.
    int longestWithinKCategories(int[] cat, int k) {
        Map<Integer, Integer> count = new HashMap<>();
        int left = 0, best = 0;
        for (int right = 0; right < cat.length; right++) {
            count.merge(cat[right], 1, Integer::sum);      // expand
            while (count.size() > k) {                     // too many distinct → shrink
                int lv = cat[left];
                count.merge(lv, -1, Integer::sum);
                if (count.get(lv) == 0) count.remove(lv);  // drop key so size is accurate
                left++;
            }
            best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

